flowchart TD
    EX[Exception from handler] --> CL["_classify_error"]
    CL --> Q{"matches _QUOTA_PATTERNS"}
    Q -->|yes| QUOTA["quota, not retriable"]
    Q -->|no| A{"matches _AUTH_PATTERNS"}
    A -->|yes| AUTH["auth, not retriable"]
    A -->|no| TN{"exc name in transient set"}
    TN -->|yes| TRANS["transient, retriable"]
    TN -->|no| SC{"status in _RETRIABLE_STATUS_CODES"}
    SC -->|yes| TRANS
    SC -->|no| BP{"matches _BUSY_PATTERNS"}
    BP -->|yes| BUSY["busy, retriable"]
    BP -->|no| GEN["generic, not retriable"]
